PINNED = {"order_id": "A-123", "deadline": "2026-07-15"}

def build_prompt(system, state, pinned):
    msgs = [{"role": "system", "content": system}]
    # pinned facts are re-injected exactly, never summarized away
    msgs.append({"role": "system", "content": f"Key facts: {pinned}"})
    if state["summary"]:
        msgs.append({"role": "system", "content": state["summary"]})
    msgs += state["recent"]
    return msgs

