def fake_summarize(prev, old_turns):
    parts = [prev] if prev else []
    parts += [m["content"] for m in old_turns]
    return " | ".join(parts)

state = {"summary": "", "recent": []}
TRIGGER = 4

def add_turn(state, content):
    state["recent"].append({"role": "user", "content": content})
    if len(state["recent"]) > TRIGGER:
        old = state["recent"][:-2]
        state["recent"] = state["recent"][-2:]
        state["summary"] = fake_summarize(state["summary"], old)
    return state

for i in range(6):
    add_turn(state, f"msg{i}")

print("summary:", state["summary"])
print("recent:", [m["content"] for m in state["recent"]])

def tokens(msgs):
    return sum(len(m["content"].split()) for m in msgs)

def summarize(prev, old):
    return (prev + " " if prev else "") + f"[{len(old)} older turns compacted]"

PINNED = {"order_id": "A-123"}
BUDGET = 8

def compact_if_needed(state):
    if tokens(state["recent"]) > BUDGET and len(state["recent"]) > 2:
        old = state["recent"][:-2]
        state["recent"] = state["recent"][-2:]
        state["summary"] = summarize(state["summary"], old)
    return state

state = {"summary": "", "recent":
         [{"role": "user", "content": f"line number {i} here"} for i in range(4)]}
state = compact_if_needed(state)

print("pinned kept:", PINNED["order_id"])
print("summary:", state["summary"])
print("recent turns:", len(state["recent"]))

