def compact(state, summarize_fn, keep_recent=2, trigger=6):
    if len(state["recent"]) > trigger:
        old = state["recent"][:-keep_recent]        # oldest turns to fold
        state["recent"] = state["recent"][-keep_recent:]  # keep tail verbatim
        state["summary"] = summarize_fn(state["summary"], old)
    return state

