def build_prompt(system, pinned, state):
    msgs = [{"role": "system", "content": system}]
    if pinned:
        msgs.append({"role": "system", "content": f"Key facts: {pinned}"})
    if state.get("summary"):
        msgs.append({"role": "system",
                     "content": f"Conversation so far: {state['summary']}"})
    msgs.extend(state.get("recent", []))   # freshest turns last
    return msgs

